import React, { useState } from 'react';
import { GameMode, Puzzle, PlayerGuess, FeedbackType } from '../types';
import { gameService } from '../lib/gameService.js';

interface TraitInputProps {
  onSubmit: (guess: string) => void;
  isDisabled: boolean;
  mode: GameMode;
}

const TraitInput: React.FC<TraitInputProps> = ({ onSubmit, isDisabled, mode }) => {
  const [input, setInput] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim()) {
      onSubmit(input.toLowerCase());
      setInput('');
    }
  };

  const placeholder = mode === 'hard' ? 'Enter the job/movie/game...' : 'Enter a trait...';

  return (
    <form onSubmit={handleSubmit} className="w-full max-w-md mx-auto">
      <div className="flex gap-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          disabled={isDisabled}
          placeholder={placeholder}
          className="flex-1 px-4 py-2 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
          autoFocus
        />
        <button
          type="submit"
          disabled={isDisabled || !input.trim()}
          className="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50"
        >
          Guess
        </button>
      </div>
    </form>
  );
};

interface GameBoardProps {
  puzzle: Puzzle;
  mode: GameMode;
  onGuess: (guess: string) => void;
  onGameOver: (won: boolean, filledSlots: (string | null)[], incorrectCount: number) => void;
}

export const GameBoard: React.FC<GameBoardProps> = ({ puzzle, mode, onGuess, onGameOver }) => {
  const [filledSlots, setFilledSlots] = useState<(string | null)[]>([null, null, null, null, null]);
  const [guesses, setGuesses] = useState<PlayerGuess[]>([]);
  const [incorrectCount, setIncorrectCount] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [gameLost, setGameLost] = useState(false);

  const getFeedbackColor = (feedback: FeedbackType): string => {
    switch (feedback) {
      case 'correct':
        return 'bg-green-500 text-white';
      case 'partial':
        return 'bg-yellow-500 text-white';
      case 'incorrect':
        return 'bg-gray-400 text-white';
    }
  };

  const getFeedbackEmoji = (feedback: FeedbackType): string => {
    switch (feedback) {
      case 'correct':
        return '🟩';
      case 'partial':
        return '🟨';
      case 'incorrect':
        return '⬜';
    }
  };

  const handleGuess = (guess: string) => {
    if (gameOver || gameLost) return;

    let result;
    let newGuess: PlayerGuess;

    if (mode === 'hard') {
      // Hard mode: guess the answer (job/movie/game)
      const isCorrect = guess.toLowerCase().trim() === puzzle.answer.toLowerCase();
      result = isCorrect ? { feedback: 'correct' as FeedbackType } : { feedback: 'incorrect' as FeedbackType };
      
      newGuess = {
        word: guess,
        feedback: result.feedback,
        matched_slot: undefined
      };

      // Add to guess history
      setGuesses([...guesses, newGuess]);

      if (result.feedback === 'correct') {
        // Fill all slots with the answer
        const newSlots = [puzzle.answer, puzzle.answer, puzzle.answer, puzzle.answer, puzzle.answer];
        setFilledSlots(newSlots);
        setGameOver(true);
        onGameOver(true, newSlots, incorrectCount);
      } else {
        // Increment incorrect count
        const newIncorrectCount = incorrectCount + 1;
        setIncorrectCount(newIncorrectCount);

        if (newIncorrectCount >= 5) {
          setGameLost(true);
          onGameOver(false, filledSlots, newIncorrectCount);
        }
      }
    } else {
      // Normal mode: guess traits
      result = gameService.validateGuess(puzzle, guess);
      newGuess = {
        word: guess,
        feedback: result.feedback,
        matched_slot: result.slotPosition
      };

      // Add to guess history
      setGuesses([...guesses, newGuess]);

      if (result.feedback === 'correct' && result.slotPosition) {
        // Fill the slot
        const newSlots = [...filledSlots];
        newSlots[result.slotPosition - 1] = guess;
        setFilledSlots(newSlots);

        // Check if won
        if (newSlots.every(slot => slot !== null)) {
          setGameOver(true);
          onGameOver(true, newSlots, incorrectCount);
        }
      } else if (result.feedback === 'incorrect') {
        // Increment incorrect count
        const newIncorrectCount = incorrectCount + 1;
        setIncorrectCount(newIncorrectCount);

        if (newIncorrectCount >= 5) {
          setGameLost(true);
          onGameOver(false, filledSlots, newIncorrectCount);
        }
      }
    }

    onGuess(guess);
  };

  return (
    <div className="w-full max-w-2xl mx-auto p-6 bg-white rounded-lg shadow-lg">
      <div className="mb-8">
        <h2 className="text-2xl font-bold mb-2">
          {mode === 'normal' ? puzzle.answer : 'Guess the Answer'}
        </h2>
        {mode === 'hard' && (
          <p className="text-gray-600 text-center">
            Guess the {puzzle.category === 'jobs' ? 'job' : puzzle.category === 'movies' ? 'movie' : 'game'} from these traits
          </p>
        )}
        {mode === 'normal' && (
          <p className="text-gray-600 text-center">
            Guess the 5 traits
          </p>
        )}
      </div>

      {/* Trait slots - only fill on exact match */}
      <div className="grid grid-cols-5 gap-2 mb-8">
        {filledSlots.map((slot, i) => {
          const traitAtPosition = puzzle.traits?.find(t => t.slot_position === i + 1);
          const displayText = slot || (mode === 'hard' ? traitAtPosition?.keyword : `${i + 1}`);
          
          return (
            <div
              key={i}
              className={`aspect-square flex items-center justify-center rounded-lg border-2 font-semibold text-sm text-center px-1 overflow-hidden ${
                slot
                  ? 'bg-green-500 text-white border-green-600'
                  : 'border-gray-300 bg-gray-50'
              }`}
            >
              <span className="break-words">{displayText}</span>
            </div>
          );
        })}
      </div>

      {/* Status info */}
      <div className="flex justify-between mb-6 text-sm font-semibold">
        {mode === 'normal' && (
          <div className="text-blue-600">
            Filled: {filledSlots.filter(s => s !== null).length}/5
          </div>
        )}
        {mode === 'hard' && (
          <div className="text-blue-600">
            Attempts: {guesses.length}
          </div>
        )}
        <div className={incorrectCount >= 5 ? 'text-red-600' : 'text-orange-600'}>
          Incorrect: {incorrectCount}/5
        </div>
      </div>

      {/* Input */}
      <div className="mb-8">
        <TraitInput onSubmit={handleGuess} isDisabled={gameOver || gameLost} mode={mode} />
      </div>

      {/* Game over states */}
      {gameOver && (
        <div className="text-center p-4 bg-green-100 rounded-lg mb-6">
          <p className="text-lg font-bold text-green-700">🎉 You won!</p>
        </div>
      )}

      {gameLost && (
        <div className="text-center p-4 bg-red-100 rounded-lg mb-6">
          <p className="text-lg font-bold text-red-700">💥 Game Over! Too many wrong guesses.</p>
          <p className="text-sm text-red-600 mt-2">The answer was: <span className="font-bold">{puzzle.answer}</span></p>
        </div>
      )}

      {/* Guess history */}
      {guesses.length > 0 && (
        <div className="mt-8">
          <h3 className="font-bold mb-3 text-sm">Guess History:</h3>
          <div className="flex flex-wrap gap-2">
            {guesses.map((guess, i) => (
              <div
                key={i}
                className={`px-3 py-1 rounded text-sm font-semibold text-white ${getFeedbackColor(
                  guess.feedback
                )}`}
              >
                {guess.word} {getFeedbackEmoji(guess.feedback)}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};
